import React from 'react';
import { StyleSheet, View, Text, TouchableOpacity } from 'react-native';

const WeeklyCalendar = ({ selectedDate, onDateSelect }) => {
  const daysOfWeek = [
    { day: 'Ngày', subDay: '/Giờ', date: '' },
    { day: '25', subDay: 'Thứ 2', date: 25 },
    { day: '26', subDay: 'Thứ 3', date: 26 },
    { day: '27', subDay: 'Thứ 4', date: 27 },
    { day: '28', subDay: 'Thứ 5', date: 28 },
    { day: '29', subDay: 'Thứ 6', date: 29 },
    { day: '30', subDay: 'Thứ 7', date: 30 },
    { day: '01', subDay: 'CN', date: 1 }
  ];

  const getDateIndicators = (date) => {
    if (date === 1) {
      return ['#FF6B35', '#FFD23F', '#8B5CF6'];
    }
    return ['#CCCCCC'];
  };

  const renderDateCell = (dayInfo, index) => {
    const { day, subDay, date } = dayInfo;
    const indicators = date ? getDateIndicators(date) : [];
    const isSelected = selectedDate === date;

    return (
      <TouchableOpacity
        key={index}
        style={[
          styles.dateCell,
          isSelected && styles.selectedDateCell
        ]}
        onPress={() => date && onDateSelect(date)}
      >
        {index === 0 ? (
          <View style={styles.timeLabelContainer}>
            <Text style={styles.timeLabelText}>{day}</Text>
            <Text style={styles.timeLabelSubText}>{subDay}</Text>
          </View>
        ) : (
          <View style={styles.dateContainer}>
            <Text style={[
              styles.dateNumber,
              date === 1 && styles.sundayDateNumber
            ]}>
              {day}
            </Text>
            <Text style={[
              styles.dayText,
              date === 1 && styles.sundayDayText
            ]}>
              {subDay}
            </Text>
            {indicators.length > 0 && (
              <View style={styles.indicatorsContainer}>
                {indicators.map((color, idx) => (
                  <View
                    key={idx}
                    style={[styles.indicator, { backgroundColor: color }]}
                  />
                ))}
              </View>
            )}
          </View>
        )}
      </TouchableOpacity>
    );
  };

  return (
    <View style={styles.container}>
      <View style={styles.daysRow}>
        {daysOfWeek.map((dayInfo, index) => renderDateCell(dayInfo, index))}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    backgroundColor: '#ffffff',
    paddingHorizontal: 0,
  },
  daysRow: {
    flexDirection: 'row',
    backgroundColor: '#F5F5F5',
    paddingVertical: 8,
  },
  dateCell: {
    flex: 1,
    alignItems: 'center',
    paddingVertical: 8,
    paddingHorizontal: 4,
  },
  selectedDateCell: {
    backgroundColor: '#FFF8DC',
  },
  dayText: {
    fontSize: 12,
    fontWeight: '500',
    color: '#666666',
    textAlign: 'center',
    marginBottom: 4,
  },
  timeLabelText: {
    fontSize: 12,
    fontWeight: '600',
    color: '#333333',
  },
  dateContainer: {
    alignItems: 'center',
  },
  dateNumber: {
    fontSize: 16,
    fontWeight: '600',
    color: '#333333',
    marginBottom: 2,
  },
  indicatorsContainer: {
    flexDirection: 'row',
    justifyContent: 'center',
  },
  indicator: {
    width: 4,
    height: 4,
    borderRadius: 2,
    marginHorizontal: 1,
  },
});

export default WeeklyCalendar;
